-- 594 original, grade-differentiated learning activities for exactly 198 existing lessons (22 countries x grades 1-3 x 3 topics).
-- All 198 lessons have the same verified original examples; no published lesson or question changed.
-- Adds three OPTIONAL activities (fill/match/MCQ), keeping existing required activity completion semantics unchanged.
-- No official-textbook equivalence, audio/speaking completion, or teacher approval is asserted.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='90s';
CREATE TEMP TABLE dadyoom_g123_594_templates ON COMMIT DROP AS
SELECT title::text,grade::integer,activity_order::integer,activity_type::text,
 activity_title::text,section::text,prompt::text,content::jsonb,answer::jsonb
