:"جملة تامة عن السقي"}]}},{"title":"كتابة جملة واضحة","grade":1,"activity_order":6,"activity_type":"multiple_choice","activity_title":"تحدي الفهم والتطبيق","section":"assessment","prompt":"كيف نختم الجملة «قرأَ الطفلُ كتابًا»؟","content":{"origin":"DADYOOM_G123_VERIFIED_EXAMPLES_594_ACTIVITIES_20261029","options":["بعلامة الاستفهام","بفاصلة فقط","بنقطة"],"educationalEvidence":"linked-to-existing-original-example","reviewStatus":"supplementary-original"},"answer":{"correct":"بنقطة"}},{"title":"كتابة جملة واضحة","grade":2,"activity_order":4,"activity_type":"fill_blank","activity_title":"أكمل من مثال الدرس","section":"practice","prompt":"أكمل جملة السقي: «___ ليلى الزهرةَ».","content":{"origin":"DADYOOM_G123_VERIFIED_EXAMPLES_594_ACTIVITIES_20261029","items":[{"sentence":"___ ليلى الزهرةَ.","options":["سقت","قرأ","نام"]}],"educationalEvidence":"linked-to-existing-original-example","reviewStatus":"supplementary-original"},"answer":{"answers":["سقت"]}},{"title":"كتابة جملة واضحة","grade":2,"activity_order":5,"activity_type":"matching","activity_title":"أصل المفهوم بمثاله","section":"practice","prompt":"صل كل كلمة أو جملة بالمعنى أو الوظيفة التي تناسبها.","content":{"origin":"DADYOOM_G123_VERIFIED_EXAMPLES_594_ACTIVITIES_20261029","left":["الطفلُ في","قرأ الطفلُ كتابًا.","سقت ليلى الزهرةَ."],"right":["جملة مكتملة عن السقي","جملة مكتملة عن القراءة","عبارة لم يكتمل معناها"],"educationalEvidence":"linked-to-existing-original-example","reviewStatus":"supplementary-original"},"answer":{"pairs":[{"left":"الطفلُ في","right":"عبارة لم يكتمل معناها"},{"left":"قرأ الطفلُ كتابًا.","right":"جملة مكتملة عن القراءة"},{"left":"سقت ليلى الزهرةَ.","right":"جملة مكتملة عن السقي"}]}},{"title":"كتابة جملة واضحة","grade":2,"activity_order":6,"activity_type":"multiple_choice","activity_title":"تحدي الفهم والتطبيق","section":"assessment","prompt":"أي تعديل يكمل عبارة «الطفلُ في»؟","content":{"origin":"DADYOOM_G123_VERIFIED_EXAMPLES_594_ACTIVITIES_20261029","options":["الطفلُ في المدرسةِ.","الطفلُ في","الطفلُ في في"],"educationalEvidence":"linked-to-existing-original-example","reviewStatus":"supplementary-original"},"answer":{"correct":"الطفلُ في المدرسةِ."}},{"title":"كتابة جملة واضحة","grade":3,"activity_order":4,"activity_type":"fill_blank","activity_title":"أكمل من مثال الدرس","section":"practice","prompt":"أكمل عبارة المكان لتصبح جملة واضحة: «الطفلُ في ___».","content":{"origin":"DADYOOM_G123_VERIFIED_EXAMPLES_594_ACTIVITIES_20261029","items":[{"sentence":"الطفلُ في ___.","options":["المدرسةِ","في","يقرأُ"]}],"educationalEvidence":"linked-to-existing-original-example","reviewStatus":"supplementary-original"},"answer":{"answers":["المدرسةِ"]}},{"title":"كتابة جملة واضحة","grade":3,"activity_order":5,"activity_type":"matching","activity_title":"أصل المفهوم بمثاله","section":"practice","prompt":"صل كل كلمة أو جملة بالمعنى أو الوظيفة التي تناسبها.","content":{"origin":"DADYOOM_G123_VERIFIED_EXAMPLES_594_ACTIVITIES_20261029","left":["قرأ الطفلُ كتابًا.","الطفلُ في","سقت ليلى الزهرةَ."],"right":["جملة سقي مكتملة","عبارة غير مكتملة","جملة قراءة مكتملة"],"educationalEvidence":"linked-to-existing-original-example","reviewStatus":"supplementary-original"},"answer":{"pairs":[{"left":"قرأ الطفلُ كتابًا.","right":"جملة قراءة مكتملة"},{"left":"الطفلُ في","right":"عبارة غير مكتملة"},{"left":"سقت ليلى الزهرةَ.","right":"جملة سقي مكتملة"}]}},{"title":"كتابة جملة واضحة","grade":3,"activity_order":6,"activity_type":"multiple_choice","activity_title":"تحدي الفهم والتطبيق","section":"assessment","prompt":"أيّ صياغة تعبّر بوضوح عن حدث السقي وتضع علامة الوقف الصحيحة؟","content":{"origin":"DADYOOM_G123_VERIFIED_EXAMPLES_594_ACTIVITIES_20261029","options":["الزهرة ليلى سقت؟","سقت ليلى الزهرةَ.","سقت الزهرة ليلى،"],"educationalEvidence":"linked-to-existing-original-example","reviewStatus":"supplementary-original"},"answer":{"correct":"سقت ليلى الزهرةَ."}},{"title":"مراجعة مهاراتي الأساسية","grade":1,"activity_order":4,"activity_type":"fill_blank","activity_title":"أكمل من مثال الدرس","section":"practice","prompt":"أكمل المثال: «زرعَ ___ وردةً في الحديقةِ».","content":{"origin":"DADYOOM_G123_VERIFIED_EXAMPLES_594_ACTIVITIES_20261029","items":[{"sentence":"زرعَ ___ وردةً في الحديقةِ.","options":["سامرٌ","الزهرةُ","الكتابُ"]}],"educationalEvidence":"linked-to-existing-original-example","reviewStatus":"supplementary-original"},"answer":{"answers":["سامرٌ"]}},{"title":"مراجعة مهاراتي الأساسية","grade":1,"activity_order":5,"activity_type":"matching","activity_title":"أصل المفهوم بمثاله","section":"practice","prompt":"صل كل كلمة أو جملة بالمعنى أو الوظيفة التي تناسبها.","content":{"origin":"DADYOOM_G123_VERIFIED_EXAMPLES_594_ACTIVITIES_20261029","left":["سامرٌ","وردةً","الحديقةِ"],"right":["مكان الزراعة","الشخص الذي زرع","ما زُرع"],"educationalEvidence":"linked-to-existing-original-example","reviewStatus":"supplementary-original"},"answer":{"pairs":[{"left":"سامرٌ","right":"الشخص الذي زرع"},{"left":"وردةً","right":"ما زُرع"},{"left":"الحديقةِ","right":"مكان الزراعة"}]}},{"title":"مراجعة مهاراتي الأساسية","grade":1,"activity_order":6,"activity_type":"multiple_choice","activity_title":"تحدي الفهم والتطبيق","section":"assessment","prompt":"بأي حرف تبدأ كلمة «زرعَ»؟","content":{"origin":"DADYOOM_G123_VERIFIED_EXAMPLES_594_ACTIVITIES_20261029","options":["الراء","الزاي","العين"],"educationalEvidence":"linked-to-existing-original-example","reviewStatus":"supplementary-original"},"answer":{"correct":"الزاي"}},{"title":"مراجعة مهاراتي الأساسية","grade":2,"activity_order":4,"activity_type":"fill_blank","activity_title":"أكمل من مثال الدرس","section":"practice","prompt":"أكمل العبارة لتوضح المكان: «زرعَ سامرٌ وردةً في ___».","content":{"origin":"DADYOOM_G123_VERIFIED_EXAMPLES_594_ACTIVITIES_20261029","items":[{"sentence":"زرعَ سامرٌ وردةً في ___.","options":["الكتابِ","المدرسةِ","الحديقةِ"]}],"educationalEvidence":"linked-to-existing-original-example","reviewStatus":"supplementary-original"},"answer":{"answers":["الحديقةِ"]}},{"title":"مراجعة مهاراتي الأساسية","grade":2,"activity_order":5,"activity_type":"matching","activity_title":"أصل المفهوم بمثاله","section":"practice","prompt":"صل كل كلمة أو جملة بالمعنى أو الوظيفة التي تناسبها.","content":{"origin":"DADYOOM_G123_VERIFIED_EXAMPLES_594_ACTIVITIES_20261029","left":["زرعَ","سامرٌ","في الحديقةِ"],"right":["مكان الحدث","الفاعل","الفعل"],"educationalEvidence":"linked-to-existing-original-example","reviewStatus":"supplementary-original"},"answer":{"pairs":[{"left":"زرعَ","right":"الفعل"},{"left":"سامرٌ","right":"الفاعل"},{"left":"في الحديقةِ","right":"مكان الحدث"}]}},{"title":"مراجعة مهاراتي الأساسية","grade":2,"activity_order":6,"activity_type":"multiple_choice","activity_title":"تحدي الفهم والتطبيق","section":"assessment","prompt":"ما المعلومة التي يخبرنا بها التعبير «في الحديقةِ»؟","content":{"origin":"DADYOOM_G123_VERIFIED_EXAMPLES_594_ACTIVITIES_20261029","options":["مكان الزراعة","زمن الزراعة","اسم الزهرة"],"educationalEvidence":"linked-to-existing-original-example","reviewStatus":"supplementary-original"},"answer":{"correct":"مكان الزراعة"}},{"title":"مراجعة مهاراتي الأساسية","grade":3,"activity_order":4,"activity_type":"fill_blank","activity_title":"أكمل من مثال الدرس","section":"practice","prompt":"أكمل المثال بفعل مناسب: «___ سامرٌ وردةً في الحديقةِ».","content":{"origin":"DADYOOM_G123_VERIFIED_EXAMPLES_594_ACTIVITIES_20261029","items":[{"sentence":"___ سامرٌ وردةً في الحديقةِ.","options":["قرأَ","زرعَ","رسمَ"]}],"educationalEvidence":"linked-to-existing-original-example","reviewStatus":"supplementary-original"},"answer":{"answers":["زرعَ"]}},{"title":"مراجعة مهاراتي الأساسية","grade":3,"activity_order":5,"activity_type":"matching","activity_title":"أصل المفهوم بمثاله","section":"practice","prompt":"صل كل كلمة أو جملة بالمعنى أو الوظيفة التي تناسبها.","content":{"origin":"DADYOOM_G123_VERIFIED_EXAMPLES_594_ACTIVITIES_20261029","left":["زرعَ","سامرٌ","وردةً"],"right":["فاعل","مفعول به","فعل"],"educationalEvidence":"linked-to-existing-original-example","reviewStatus":"supplementary-original"},"answer":{"pairs":[{"left":"زرعَ","right":"فعل"},{"left":"سامرٌ","right":"فاعل"},{"left":"وردةً","right":"مفعول به"}]}},{"title":"مراجعة مهاراتي الأساسية","grade":3,"activity_order":6,"activity_type":"multiple_choice","activity_title":"تحدي الفهم والتطبيق","section":"assessment","prompt":"أي جملة تحافظ على المكان والمفعول به مع تغيير الفعل إلى مرادفه؟","content":{"origin":"DADYOOM_G123_VERIFIED_EXAMPLES_594_ACTIVITIES_20261029","options":["قطف سامر وردة من الصف.","غرس سامر وردةً في الحديقةِ.","غرس سامر شجرةً في الملعبِ."],"educationalEvidence":"linked-to-existing-original-example","reviewStatus":"supplementary-original"},"answer":{"correct":"غرس سامر وردةً في الحديقةِ."}}]$dadyoom_json$::jsonb)
AS x(title text,grade integer,activity_order integer,activity_type text,
activity_title text,section text,prompt text,content jsonb,answer jsonb);

DO $safe$
DECLARE
  lesson_count integer;
  existing_activity_count integer;
  learner_activity_attempts integer;
  inserted_count integer;
BEGIN
  IF (SELECT COUNT(*) FROM pg_temp.dadyoom_g123_594_templates)<>27 THEN
    RAISE EXCEPTION 'Expected 27 unique topic/grade/activity templates';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_temp.dadyoom_g123_594_templates
             GROUP BY title,grade,activity_order HAVING COUNT(*)<>1) THEN
    RAISE EXCEPTION 'Duplicate activity template';
  END IF;
  WITH lessons AS (
    SELECT l.id,l.title,g.grade_number grade,
       COUNT(a.id) FILTER(WHERE a.is_published) AS published_count,
       COUNT(DISTINCT a.activity_order) AS order_count,
       MAX(a.activity_order) AS max_order
    FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id
    JOIN public.curricula c ON c.id=g.curriculum_id
    JOIN public.countries co ON co.id=c.country_id
    LEFT JOIN public.lesson_activities a ON a.lesson_id=l.id
    WHERE l.status='published' AND g.grade_number BETWEEN 1 AND 3
      AND l.title IN ('الجملة الفعلية البسيطة','كتابة جملة واضحة','مراجعة مهاراتي الأساسية')
      AND CASE l.title
        WHEN 'الجملة الفعلية البسيطة' THEN l.content ILIKE '%زرعَ الطفلُ زهرةً%' AND l.content ILIKE '%الفلاحُ، سقى، الزرعَ%'
        WHEN 'كتابة جملة واضحة' THEN l.content ILIKE '%قرأَ الطفلُ كتابًا%' AND l.content ILIKE '%الزهرةَ / سقت / ليلى%'
        WHEN 'مراجعة مهاراتي الأساسية' THEN l.content ILIKE '%زرعَ سامرٌ وردةً%' AND l.content ILIKE '%تبدأ بزاي%'
        ELSE false END
    GROUP BY l.id,l.title,g.grade_number
  )
  SELECT COUNT(*),COALESCE(SUM(published_count),0)
    INTO lesson_count,existing_activity_count
  FROM lessons WHERE published_count=3 AND order_count=3 AND max_order=3;
  IF lesson_count<>198 OR existing_activity_count<>594 THEN
    RAISE EXCEPTION 'Abort: expected 198 intact example-linked lessons with 3 existing activities, got %',lesson_count;
  END IF;
  SELECT COUNT(*) INTO learner_activity_attempts
  FROM public.lesson_activity_attempts aa
    JOIN public.lesson_activities la ON la.id=aa.activity_id
    JOIN public.lessons l ON l.id=la.lesson_id
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id
  WHERE l.status='published' AND g.grade_number BETWEEN 1 AND 3
    AND l.title IN ('الجملة الفعلية البسيطة','كتابة جملة واضحة','مراجعة مهاراتي الأساسية');
  IF learner_activity_attempts<>0 OR EXISTS(
    SELECT 1 FROM public.student_lesson_progress sp JOIN public.lessons l ON l.id=sp.lesson_id
    JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
    WHERE l.status='published' AND g.grade_number BETWEEN 1 AND 3
      AND l.title IN ('الجملة الفعلية البسيطة','كتابة جملة واضحة','مراجعة مهاراتي الأساسية')
  ) THEN
    RAISE EXCEPTION 'Abort: existing learner attempts or progress records';
  END IF;

  INSERT INTO public.lesson_activities
    (lesson_id,title,activity_type,instructions,content,activity_order,
     points,is_published,section,prompt,answer,is_required)
  SELECT l.id,t.activity_title,t.activity_type,
    'تدريب إثرائي أصلي من أمثلة الدرس؛ شارك معلمك في مراجعة الفهم.',
    t.content,t.activity_order,5,true,t.section,t.prompt,t.answer,false
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
  JOIN public.grades g ON g.id=u.grade_id
  JOIN public.curricula c ON c.id=g.curriculum_id
  JOIN public.countries co ON co.id=c.country_id
  JOIN pg_temp.dadyoom_g123_594_templates t
    ON t.title=l.title AND t.grade=g.grade_number
  WHERE l.status='published'
    AND CASE l.title
      WHEN 'الجملة الفعلية البسيطة' THEN l.content ILIKE '%زرعَ الطفلُ زهرةً%' AND l.content ILIKE '%الفلاحُ، سقى، الزرعَ%'
      WHEN 'كتابة جملة واضحة' THEN l.content ILIKE '%قرأَ الطفلُ كتابًا%' AND l.content ILIKE '%الزهرةَ / سقت / ليلى%'
      WHEN 'مراجعة مهاراتي الأساسية' THEN l.content ILIKE '%زرعَ سامرٌ وردةً%' AND l.content ILIKE '%تبدأ بزاي%'
      ELSE false END;
  GET DIAGNOSTICS inserted_count=ROW_COUNT;
  IF inserted_count<>594 THEN
    RAISE EXCEPTION 'Rollback: inserted % rather than 594 activities',inserted_count;
  END IF;
  RAISE NOTICE 'DADYOOM_G123_ORIGINAL_OPTIONAL_ACTIVITIES_ADDED=%',inserted_count;
END
$safe$;
COMMIT;
-- Confirm with independent read-only production SELECT before reporting completion.
